(function(){
  var $=function(id){return document.getElementById(id)};
  var money=function(n){return n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})};
  var mode='from';
  function run(){
    var cost=+$('cost').value||0, extra=+$('extra').value||0, qty=+$('qty').value||0;
    var totalCost=cost+extra, price, margin;
    if(mode==='from'){
      price=+$('price').value||0;
      margin = price>0 ? (price-totalCost)/price*100 : 0;
    } else {
      margin=+$('price').value||0;
      // price from margin: price = cost / (1 - margin/100)
      if(margin>=100){ $('note').textContent='A margin of 100% or more is impossible, because the price would have to be infinite.'; margin=99.99; }
      price = totalCost/(1-margin/100);
    }
    var profit=price-totalCost;
    var markup = totalCost>0 ? profit/totalCost*100 : 0;
    $('margin').textContent=margin.toFixed(1)+'%';
    $('markup').textContent=markup.toFixed(1)+'%';
    $('each').textContent=money(profit);
    $('total').textContent=money(profit*qty);
    [$('margin'),$('markup'),$('each'),$('total')].forEach(function(e){
      e.classList.toggle('pm-loss', profit<0);
    });
    $('brk').innerHTML=
      '<div><span>Selling price</span><b>'+money(price)+'</b></div>'+
      '<div><span>Cost per unit</span><b>'+money(cost)+'</b></div>'+
      (extra?'<div><span>Other costs per unit</span><b>'+money(extra)+'</b></div>':'')+
      '<div><span>Total cost per unit</span><b>'+money(totalCost)+'</b></div>'+
      '<div><span>Revenue on '+qty+' units</span><b>'+money(price*qty)+'</b></div>';
    if(profit<0) $('note').textContent='You are selling below cost. Every unit loses '+money(-profit)+'.';
    else if(mode==='to') $('note').textContent='To make a '+margin.toFixed(1)+'% margin you need to charge '+money(price)+'.';
    else $('note').textContent='Margin is profit as a share of the PRICE. Markup is the same profit as a share of the COST. They are never the same number and mixing them up is the most expensive mistake in pricing.';
    if(window.WT) WT.resize();
  }
  $('tabs').addEventListener('click',function(e){
    var b=e.target.closest('button[data-m]'); if(!b) return;
    mode=b.dataset.m;
    [].forEach.call(this.querySelectorAll('button'),function(x){x.classList.toggle('active',x===b)});
    if(mode==='to'){ $('lab2').querySelector('span').textContent='Margin you want %'; $('price').value='40'; }
    else { $('lab2').querySelector('span').textContent='Selling price'; $('price').value='15'; }
    run();
  });
  ['cost','price','extra','qty'].forEach(function(id){$(id).addEventListener('input',run)});
  $('copy').addEventListener('click',function(){
    var ok=WT.copy('Margin '+$('margin').textContent+', markup '+$('markup').textContent+
      ', profit '+$('each').textContent+' each and '+$('total').textContent+' in total.');
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy result'},1400);
  });
  run();
})();
